import React, { Component } from 'react';
import Teacherheader from '../components/Teacherheader';
import axios from 'axios';
import Resultrecords from './Resultrecords';

  
class Searchstudents extends Component{

   state = {
       searchstring: '',
       results: [{}],
       foundrecords: false,
       displaymessage: false,
       records:[{}]
    }

   searchrecords = (event) => {
        event.preventDefault();
        console.log("BEfore axios call - search str",this.state.searchstring)
        axios.get(`/api/teacher/search/${this.state.searchstring}`)
            .then((response) => {
                console.log("Results from search",response);
                let matchrecords = [];
                let found = false;
                let displaymessage = false;
                if ((response.data.studentdetails.length > 0) ||
                    (response.data.batchdetails.length > 0))
                {   found = true;
                    displaymessage = false
                    for (let i =0; i < response.data.studentdetails.length; i++)
                    {
                        
                        let currentrec = {
                            field1 : response.data.studentdetails[i]._id,
                            field2 : "Student: "+ response.data.studentdetails[i].studentfname+ " "+response.data.studentdetails[i].studentlname,
                            field3: response.data.studentdetails[i].loginemail,
                            field4 : response.data.studentdetails[i].parentname,
                            field5 : response.data.studentdetails[i].parentphonenumber,
                            field6 : response.data.studentdetails[i].batchdesc
                        }
                        matchrecords.push(currentrec)
                    } 
                    for (let i =0; i < response.data.batchdetails.length; i++)
                    {
                      
                       let currentrec = {
                           field1 : response.data.batchdetails[i]._id,
                           field2: "Batch: "+ response.data.batchdetails[i].batchdesc,
                           field3: response.data.batchdetails[i].subject,
                           field4 : response.data.batchdetails[i].level,
                           field5 : response.data.batchdetails[i].rateperhour,
                           field6 : "Number of Students: "+response.data.batchdetails[i].students.length
                       }
                       matchrecords.push(currentrec)
                    }   
                } 
                else{
                     displaymessage = true
                     found = false;
                }  
                this.setState({results: matchrecords,
                               foundrecords: found,
                               displaymessage : displaymessage},
                    () => {
                        console.log("State",this.state.results,'found', this.state.foundrecords);
                    });
            })
            .catch((err) => {
                console.log("The error:",err);
            });
   }

   handleInputChange = (event) => {
    const target = event.target;
    const value = target.value;
    const name  = target.name;
    //console.log('The Value in input change',value,name);

    this.setState({
       [name]: value
     });
};
 
    render(){
        let resultset = this.state.results
       
        return(<div><Teacherheader />
            <h4>Search Student Details </h4>
            <form className="inputsection">
                  <div className = "form-group row">
                               <label forhtml = "searchstring" id ="lsearchstr">Search By Student Name / Email / Parentname  </label><br />
                         <input className="textarea" onChange  = {this.handleInputChange} type="text" name="searchstring"  value={this.state.searchstring} /><br />.
                         <button name = "searchbtn" onClick = {this.searchrecords}>Search</button>
                  </div>
             </form> 
             {this.state.foundrecords  ?
              <div>{resultset.map((data,index) =>
                   <Resultrecords field1 = {data.field1} 
                               key={index}
                               field2 = {data.field2}
                               field3 = {data.field3}
                               field4 = {data.field4}
                               field5 = {data.field5}
                               field6 = {data.field6}
                                /> )}
                </div> :<div></div>} 
              {this.state.displaymessage ? <div>No Student details found</div>:<div></div>}          
        </div>);
    }
    
}
export default Searchstudents;

  


